STEPS.append('p=\'App/Sources/Pointer.swift\'; s=open(p).read()\n# 1. a dot for the system pointer, and the demo entry point\nold=\'\'\'        let hider = UIPointerInteraction(delegate: self)\n        hider.isEnabled = false\n        page.view.addInteraction(hider)\n        self.hider = hider\n    }\n\'\'\'\nnew=\'\'\'        let hider = UIPointerInteraction(delegate: self)\n        hider.isEnabled = false\n        page.view.addInteraction(hider)\n        self.hider = hider\n        #if DEBUG\n        startDemo()\n        #endif\n    }\n\n    #if DEBUG\n    // DEMO ONLY (a recording\'s scratch build, never committed): the simulator has no trackpad, so a\n    // scripted pointer stands in for one. A script dropped at $EGLU_DATA_ROOT/pointer-go.json plays\n    // through the page as the iPhone\'s desktop view\'s pointer does (bridge.js pointer, type), and the\n    // cursor is drawn where it is: the page\'s own picture, or a dot as iPadOS draws its pointer.\n    private let demoDot = UIView()\n    private var demoOn = false\n\n    private func startDemo() {\n        guard let root = ProcessInfo.processInfo.environment["EGLU_DATA_ROOT"], !root.isEmpty else { return }\n        demoDot.isUserInteractionEnabled = false\n        demoDot.isHidden = true\n        demoDot.backgroundColor = UIColor(white: 0.32, alpha: 0.55)\n        demoDot.layer.cornerRadius = 9.5\n        demoDot.layer.borderColor = UIColor(white: 1, alpha: 0.35).cgColor\n        demoDot.layer.borderWidth = 0.5\n        demoDot.frame = CGRect(x: 0, y: 0, width: 19, height: 19)\n        page?.view.addSubview(demoDot)\n        let go = URL(fileURLWithPath: root).appendingPathComponent("pointer-go.json")\n        Task { @MainActor [weak self] in\n            while self != nil {\n                if let data = try? Data(contentsOf: go) {\n                    try? FileManager.default.removeItem(at: go)\n                    await self?.play(data, log: URL(fileURLWithPath: root).appendingPathComponent("pointer-log.txt"))\n                }\n                try? await Task.sleep(for: .milliseconds(200))\n            }\n        }\n    }\n\n    private struct DemoStep: Decodable { let t: Double; let x: Double; let y: Double; let type: String; let key: String? }\n\n    private func play(_ data: Data, log: URL) async {\n        guard let steps = try? JSONDecoder().decode([DemoStep].self, from: data) else { return }\n        demoOn = true\n        let start = CACurrentMediaTime()\n        var lines = ["start \\\\(Date().timeIntervalSince1970)"]\n        var held = false\n        for step in steps {\n            let wait = step.t - (CACurrentMediaTime() - start)\n            if wait > 0 { try? await Task.sleep(for: .seconds(wait)) }\n            guard let page else { break }\n            let point = CGPoint(x: step.x, y: step.y)\n            switch step.type {\n            case "key":\n                page.type(step.key ?? "", back: 0)\n                lines.append("key \\\\(step.key ?? "") \\\\(CACurrentMediaTime() - start)")\n            case "down":\n                held = true\n                pressed = point\n                page.pointer("down", at: point, button: 0, buttons: 1)\n                lines.append("down \\\\(Int(step.x)),\\\\(Int(step.y)) \\\\(CACurrentMediaTime() - start)")\n            case "up":\n                held = false\n                pressed = nil\n                page.pointer("up", at: point)\n                lines.append("up \\\\(Int(step.x)),\\\\(Int(step.y)) \\\\(CACurrentMediaTime() - start)")\n            default:\n                if held { pressed = point }\n                page.pointer("move", at: point, buttons: held ? 1 : 0)\n            }\n            cursor = point\n            lastHover = CACurrentMediaTime()\n            updateCursor()\n        }\n        lines.append("end \\\\(CACurrentMediaTime() - start)")\n        try? lines.joined(separator: "\\\\n").write(to: log, atomically: true, encoding: .utf8)\n    }\n    #endif\n\'\'\'\nassert old in s; s=s.replace(old,new)\n# 2. the dot where no picture is drawn\nold2=\'\'\'        hideSystemPointer(hide)\n        guard let point, let picture else {\n            drawn.isHidden = true\n            return\n        }\'\'\'\nnew2=\'\'\'        hideSystemPointer(hide)\n        #if DEBUG\n        if demoOn {\n            demoDot.isHidden = point == nil || picture != nil || hide\n            if let point, picture == nil {\n                demoDot.center = point\n                demoDot.superview?.bringSubviewToFront(demoDot)\n            }\n        }\n        #endif\n        guard let point, let picture else {\n            drawn.isHidden = true\n            return\n        }\'\'\'\nassert old2 in s; s=s.replace(old2,new2)\nopen(p,\'w\').write(s)')

